import{_ as a,o as t,c as o,a4 as l}from"./chunks/framework.DzJZdBQK.js";const c=JSON.parse('{"title":"写作课作业-116","description":"","frontmatter":{"date":"2021-04-05T21:19:03","title":"写作课作业-116","categories":["写作","作业","区块链小白书"],"tags":["写作","作业","区块链小白书"]},"headers":[{"level":2,"title":"2W1H","slug":"_2w1h","link":"#_2w1h","children":[{"level":3,"title":"What","slug":"what","link":"#what","children":[]},{"level":3,"title":"Why","slug":"why","link":"#why","children":[]},{"level":3,"title":"How","slug":"how","link":"#how","children":[]}]},{"level":2,"title":"我的思考","slug":"我的思考","link":"#我的思考","children":[]}],"relativePath":"posts/homework/116.md","filePath":"posts/homework/116.md"}'),r={name:"posts/homework/116.md"};function i(h,e,n,p,s,d){return t(),o("div",null,[...e[0]||(e[0]=[l('<blockquote><p>《区块链小白书》之《区块链》</p></blockquote><h2 id="_2w1h" tabindex="-1">2W1H <a class="header-anchor" href="#_2w1h" aria-label="Permalink to &quot;2W1H&quot;">​</a></h2><h3 id="what" tabindex="-1">What <a class="header-anchor" href="#what" aria-label="Permalink to &quot;What&quot;">​</a></h3><ul><li>区块链是支撑比特币的底层技术</li><li>所谓山寨币，就是对比特币进行了事实上并没有什么用的改造，然后取一个什么名字，然后就发布的所谓下一个比特币，下一个机会……</li><li>公链，顾名思义，剧场公众都可以使用的区块链。</li><li>共识机制，比特币所采用的共识算法是 PoW（Proof of Work，工作量证明机制），简单讲，就是网络中的节点根据自己的贡献获得权益，多劳多得。dPoS（<a href="https://en.wikipedia.org/wiki/Proof_of_stake#Delegated_Proof-of-Stake" target="_blank" rel="noreferrer">Delegated Proof of Stake</a>）是 PoS（<a href="https://en.wikipedia.org/wiki/Proof_of_stake" target="_blank" rel="noreferrer">Proof of Stake</a>）的进一步改良。简单讲，就是你作为持币者，可以通过持有量和持有时间的多少获得权益。</li><li>山寨链是对基础共识机制的抄袭。</li><li>打造一个不可篡改的分布式数据库，是目的，而区块链技术，是达成这个目的的手段。</li><li>恒信网络是世界上第一个已被证明为可行的无币区块链解决方案，特点有：支持大规模高并发；兼容各种其他公链；智能合约与恒信网络本身无关，恒信网络却能提供智能合约（其实就是各种程序）的完全透明运行环境。</li><li>分布式账簿的解决方案之中，比特币的区块链技术理论上应该是其中的一支 —— 目前已有很多其它的可行解决方案，比如上文中提到的基于 dPoS 的 EOS 和基于 DAG + TEE 的 Mixin Network。</li></ul><h3 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to &quot;Why&quot;">​</a></h3><p>人们开始琢磨：“这个区块链技术还可以用在什么地方呢？” —— 当然，人们琢磨得最多的还有另外一个问题：“我应该如何获利呢？”</p><p>世界有容错性，山寨币，山寨链会存活挺长一段时间的，一些山寨币或者山寨链，还也可能不会消失。</p><p>当关注目的的时候，就会看到不同的手段，不同的解决方案。</p><h3 id="how" tabindex="-1">How <a class="header-anchor" href="#how" aria-label="Permalink to &quot;How&quot;">​</a></h3><h2 id="我的思考" tabindex="-1">我的思考 <a class="header-anchor" href="#我的思考" aria-label="Permalink to &quot;我的思考&quot;">​</a></h2><p>如果购买数字资产，只购买主流币，当然更好的选择是前几的主流币。对于自己来说，BOX就是一个很好的选择。</p><p>如果某个项目说自己使用了区块链技术，要怀疑是否是山寨（骗子）项目。</p><p>目前区块链的发展一定会和经济，金融发生关系，而经济也好，金融也罢，关注的都是人在参与，需要多补充对“人性”的理解。</p><hr><p>欢迎联系我</p><p>微信号 ：Crazy_Airhead</p><p>Mixin ID : 1091586</p><p>定投课堂邀请码：6DYMBFP061</p><p>李笑来写作课邀请码：38MDGFYZK8</p><p>水龙头邀请码：FDJQHJ</p>',20)])])}const k=a(r,[["render",i]]);export{c as __pageData,k as default};
